#!/usr/bin/env bash
# Generated by Section 11 of 1st_Paper_Trial.ipynb -- run this ON the GCP VM.
# Detects the real Linux user and install path itself, so nothing needs hand-editing.
set -euo pipefail

INSTALL_DIR="${INSTALL_DIR:-$HOME/t212-bot}"
RUN_USER="$(id -un)"
echo "==> Installing T212 bot for user '${RUN_USER}' into ${INSTALL_DIR}"

# 1. swap: 1GB RAM is enough, but a pandas import can spike and trip the OOM killer
if ! swapon --show | grep -q /swapfile; then
  echo "==> Creating 1GB swap"
  sudo fallocate -l 1G /swapfile
  sudo chmod 600 /swapfile
  sudo mkswap /swapfile >/dev/null
  sudo swapon /swapfile
  grep -q '/swapfile' /etc/fstab || echo '/swapfile none swap sw 0 0' | sudo tee -a /etc/fstab >/dev/null
fi

# 2. UTC, so the bot's notion of "today" matches the backtest's
sudo timedatectl set-timezone UTC

# 3. dependencies
echo "==> Installing python3-venv"
sudo apt-get update -qq
sudo apt-get install -y -qq python3-venv

# 4. virtualenv
cd "${INSTALL_DIR}"
python3 -m venv venv
./venv/bin/pip install --quiet --upgrade pip
./venv/bin/pip install --quiet -r requirements.txt

# 5. credentials must already exist -- this script never handles your keys
if [ ! -f .env ]; then
  echo ""
  echo "!! ${INSTALL_DIR}/.env is missing. Create it first:"
  echo ""
  echo "   cat > ${INSTALL_DIR}/.env <<'ENVEOF'"
  echo "   T212_API_KEY=your_demo_key"
  echo "   T212_API_SECRET=your_demo_secret"
  echo "   ENVEOF"
  echo ""
  exit 1
fi
chmod 600 .env

# 6. systemd unit, written with the ACTUAL user and paths rather than a guess
sudo tee /etc/systemd/system/t212-bot.service >/dev/null <<UNIT
[Unit]
Description=Trading 212 momentum bot
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
User=${RUN_USER}
WorkingDirectory=${INSTALL_DIR}
EnvironmentFile=${INSTALL_DIR}/.env
Environment=RUN_MODE=loop
ExecStart=${INSTALL_DIR}/venv/bin/python bot.py
Restart=always
RestartSec=30

[Install]
WantedBy=multi-user.target
UNIT

sudo systemctl daemon-reload
sudo systemctl enable --now t212-bot
sleep 3
sudo systemctl --no-pager status t212-bot || true

echo ""
echo "==> Done. Watch it with:  tail -f ${INSTALL_DIR}/t212_bot.log"
